import React, { useEffect, useState } from "react";
import axios from "axios";
import "./AdminDashboard.css";
import AddUser from "./AddUser"; // ✅ Import the new AddUser component
import { Link, useNavigate } from "react-router-dom";
import { FaUserPlus, FaUsers, FaTruck, FaUserCircle, FaCaretDown } from "react-icons/fa";

function AdminDashboard() {
  const [users, setUsers] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [editUser, setEditUser] = useState(null);
  const [message, setMessage] = useState("");
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);
  const [showAddUserForm, setShowAddUserForm] = useState(false); // ✅ New state to control form visibility

  const [currentUser, setCurrentUser] = useState({
    username: 'Admin',
    email: 'admin@routemax.com',
    role: 'ADMIN',
  });

  const token = localStorage.getItem("token");
  const navigate = useNavigate();

  useEffect(() => {
    const loggedInUser = {
      username: "Admin",
      email: "admin@routemax.com",
      role: "ADMIN",
    };
    setCurrentUser(loggedInUser);

    fetchUsers();
  }, []);

  // ✅ Fetch all users
  const fetchUsers = async () => {
    try {
      const response = await axios.get("http://localhost:8080/api/admin/users", {
        headers: { Authorization: `Bearer ${token}` },
      });
      setUsers(response.data);
    } catch (error) {
      console.error("Error fetching users:", error);
      setMessage("❌ Failed to load users.");
    }
  };

  // ✅ Add new user function - remains the same, but now it's a separate function
  const handleAddUser = async (e, newUser) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:8080/api/admin/users", newUser, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      setMessage("✅ User added successfully!");
      fetchUsers();
      setShowAddUserForm(false); // Hide the form after success
    } catch (error) {
      console.error("Error adding user:", error.response?.data || error);
      setMessage("❌ Failed to add user.");
    }
  };

  // ✅ Delete user
  const handleDeleteUser = async (id) => {
    if (!window.confirm("Are you sure you want to delete this user?")) return;
    try {
      await axios.delete(`http://localhost:8080/api/admin/users/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setMessage("✅ User deleted successfully!");
      fetchUsers();
    } catch (error) {
      console.error("Error deleting user:", error.response?.data || error);
      setMessage("❌ Failed to delete user.");
    }
  };

  // ✅ Edit user submit
  const handleEditUser = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:8080/api/admin/users/${editUser.id}`, editUser, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      setMessage("✅ User updated successfully!");
      setEditUser(null);
      fetchUsers();
    } catch (error) {
      console.error("Error editing user:", error.response?.data || error);
      setMessage("❌ Failed to update user.");
    }
  };

  // ✅ Filter users
  const filteredUsers = users.filter(
    (u) =>
      u.username?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="admin-dashboard-container">
      <nav className="header-nav">
        <div className="logo">RouteMax</div>
        <div className="admin-profile-dropdown">
          <div className="profile-toggle" onClick={() => setShowProfileDropdown(!showProfileDropdown)}>
            <FaUserCircle className="profile-icon" />
            <span>{currentUser.username}</span> 
            <FaCaretDown className={`dropdown-caret ${showProfileDropdown ? 'rotate' : ''}`} />
          </div>
          {showProfileDropdown && (
            <div className="profile-dropdown-content">
              <p><strong>Username:</strong> {currentUser.username}</p>
              <p><strong>Email:</strong> {currentUser.email}</p>
              <p><strong>Role:</strong> {currentUser.role}</p>
              <p><strong>Password:</strong> ••••••••</p>
            </div>
          )}
        </div>
      </nav>

      <div className="content-area">
        <div className="welcome-section">
          <h1 className="welcome-title">Welcome, {currentUser.username} 👋</h1>
          <p className="welcome-subtitle">
            Manage your parcels, users, and stay updated.
          </p>
        </div>

        <div className="card-container">
          {/* Card: Add User - Now toggles visibility of the form */}
          <div className="card" onClick={() => setShowAddUserForm(true)}>
            <h3 className="card-title">
              <FaUserPlus className="card-icon" /> Add User
            </h3>
            <p className="card-text">
              Create new user accounts for the system.
            </p>
            <span className="card-link">Add New User →</span>
          </div>

          {/* Card: View Users - Now shows the user list/table */}
          <div className="card" onClick={() => navigate('/view-users-section')}>
            <h3 className="card-title">
              <FaUsers className="card-icon" /> View Users
            </h3>
            <p className="card-text">
              Search, edit, and delete existing user accounts.
            </p>
            <span className="card-link">Manage Users →</span>
          </div>

          {/* Card: Manage Parcels */}
          <Link to="/parcels" className="card">
            <h3 className="card-title">
              <FaTruck className="card-icon" /> Manage Parcels
            </h3>
            <p className="card-text">
              Oversee and update all parcel delivery statuses.
            </p>
            <span className="card-link">Go to Parcels →</span>
          </Link>
        </div>

        <div className="user-management-section">
          <h2 className="section-title">Admin Dashboard - User Management</h2>
          
          {/* ✅ Conditionally render the AddUser component */}
          {showAddUserForm && <AddUser onAddUser={handleAddUser} message={message} />}

          <div id="view-users-section" className="section-block">
            <h3 className="section-subtitle">View and Manage Existing Users</h3>
            <input
              type="text"
              placeholder="Search by username or email"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
            {editUser && (
              <form onSubmit={handleEditUser} className="edit-user-form">
                <h3>Edit User: {editUser.username}</h3>
                <input
                  type="text"
                  value={editUser.username}
                  onChange={(e) => setEditUser({ ...editUser, username: e.target.value })}
                  required
                />
                <input
                  type="email"
                  value={editUser.email}
                  onChange={(e) => setEditUser({ ...editUser, email: e.target.value })}
                  required
                />
                <input
                  type="password"
                  placeholder="(leave blank to keep same)"
                  onChange={(e) => setEditUser({ ...editUser, password: e.target.value })}
                />
                <select
                  value={editUser.role}
                  onChange={(e) => setEditUser({ ...editUser, role: e.target.value })}
                >
                  <option value="USER">USER</option>
                  <option value="ADMIN">ADMIN</option>
                </select>
                <button type="submit">Save Changes</button>
                <button type="button" onClick={() => setEditUser(null)}>
                  Cancel
                </button>
              </form>
            )}

            <table className="users-table">
              <thead>
                <tr>
                  <th>ID</th>
                  <th>Username</th>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredUsers.map((u) => (
                  <tr key={u.id}>
                    <td>{u.id}</td>
                    <td>{u.username}</td>
                    <td>{u.email}</td>
                    <td>{u.role}</td>
                    <td>
                      <button onClick={() => setEditUser(u)}>Edit</button>
                      <button onClick={() => handleDeleteUser(u.id)}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

export default AdminDashboard;
